INSERT INTO collection (id, code, name_fr, name_ar, name_en, default_audience, default_classification, default_risk_tier, chunking_policy, description_fr, description_ar, description_en, enabled) VALUES
  ('31013ce2-56b9-55c8-850e-72f0d695d3f5', 'PRODUCT_SHEETS', 'Fiches produits', 'بطاقات المنتجات', 'Product sheets', 'PUBLIC', 'PUBLIC', 'T2_MEDIUM', '{"strategy":"HEADING_BLOCK","minTokens":400,"maxTokens":700,"rule":"heading-aware; one chunk per condition block (éligibilité, montant, durée, marge, garanties, pièces)","source":"docs/04 §15"}', 'Product sheets — 24 manifest chunk(s), 8 document(s). Defaults derived from specs/eval/kb-manifest.jsonl.', 'Fiches produits — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Product sheets — defaults derived from specs/eval/kb-manifest.jsonl.', true),
  ('849122d4-9a39-5bce-ba99-19d3070a1165', 'TARIFFS', 'Barèmes et tarifs', 'التعريفات البنكية', 'Tariff booklets', 'PUBLIC', 'PUBLIC', 'T2_MEDIUM', '{"strategy":"TABLE_ROW","minTokens":80,"maxTokens":200,"rule":"one row = one chunk, never split a table row; the header is repeated in every chunk","source":"docs/04 §15"}', 'Tariff booklets — 5 manifest chunk(s), 2 document(s). Defaults derived from specs/eval/kb-manifest.jsonl.', 'Barèmes et tarifs — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Tariff booklets — defaults derived from specs/eval/kb-manifest.jsonl.', true),
  ('182c6b05-2780-5a85-ad43-4b446c0d016e', 'PROCEDURES', 'Procédures', 'الإجراءات', 'Procedures', 'PUBLIC', 'PUBLIC', 'T1_LOW', '{"strategy":"STEP_SEQUENCE","minTokens":300,"maxTokens":600,"rule":"one numbered step sequence per chunk; steps are never split mid-sequence","source":"docs/04 §15"}', 'Procedures — 2 manifest chunk(s), 1 document(s). Defaults derived from specs/eval/kb-manifest.jsonl.', 'Procédures — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Procedures — defaults derived from specs/eval/kb-manifest.jsonl.', true);
INSERT INTO collection (id, code, name_fr, name_ar, name_en, default_audience, default_classification, default_risk_tier, chunking_policy, description_fr, description_ar, description_en, enabled) VALUES
  ('ccc2f637-eeeb-5f67-aa34-5b25fa9da945', 'REGULATION', 'Textes réglementaires', 'النصوص التشريعية والترتيبية', 'Regulation', 'AGENT', 'INTERNAL', 'T3_HIGH', '{"strategy":"ARTICLE","minTokens":200,"maxTokens":800,"rule":"per article, with the article number carried in heading_path (loi 2016-48, circulaires BCT)","source":"docs/04 §15"}', 'Regulation — 3 manifest chunk(s), 1 document(s). Defaults derived from specs/eval/kb-manifest.jsonl.', 'Textes réglementaires — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Regulation — defaults derived from specs/eval/kb-manifest.jsonl.', true),
  ('4ed97b79-15bb-5b31-aa2e-173f115664e0', 'DIRECTORY', 'Annuaire et agences', 'دليل الوكالات', 'Branch directory', 'PUBLIC', 'PUBLIC', 'T1_LOW', '{"strategy":"TABLE_ROW","minTokens":80,"maxTokens":200,"rule":"one row = one chunk; an agency is retrieved whole or not at all","source":"docs/04 §15"}', 'Branch directory — 4 manifest chunk(s), 1 document(s). Defaults derived from specs/eval/kb-manifest.jsonl.', 'Annuaire et agences — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Branch directory — defaults derived from specs/eval/kb-manifest.jsonl.', true),
  ('acbf1647-733a-5c18-8591-3e66f89143ad', 'GLOSSARY', 'Glossaire', 'المعجم', 'Glossary', 'PUBLIC', 'PUBLIC', 'T3_HIGH', '{"strategy":"ENTRY","minTokens":100,"maxTokens":300,"rule":"one term = one chunk, so a definition is never split from its term","source":"docs/04 §15"}', 'Glossary — 6 manifest chunk(s), 1 document(s). Defaults derived from specs/eval/kb-manifest.jsonl.', 'Glossaire — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Glossary — defaults derived from specs/eval/kb-manifest.jsonl.', true);
INSERT INTO collection (id, code, name_fr, name_ar, name_en, default_audience, default_classification, default_risk_tier, chunking_policy, description_fr, description_ar, description_en, enabled) VALUES
  ('2dff83a8-cb66-5740-bdb3-f15a53b7fd26', 'GUIDES', 'Guides clients', 'أدلة الحرفاء', 'Customer guides', 'PUBLIC', 'PUBLIC', 'T1_LOW', '{"strategy":"HEADING_BLOCK","minTokens":400,"maxTokens":700,"rule":"heading-aware; one chunk per question or section","source":"docs/04 §15"}', 'Customer guides — 4 manifest chunk(s), 2 document(s). Defaults derived from specs/eval/kb-manifest.jsonl.', 'Guides clients — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Customer guides — defaults derived from specs/eval/kb-manifest.jsonl.', true),
  ('66832258-fa36-5f5b-8cf3-8fd9a0d32a8e', 'SHARIA_NOTES', 'Notes et avis du Comité', 'ملاحظات وآراء اللجنة', 'Sharia notes and committee opinions', 'PUBLIC', 'PUBLIC', 'T3_HIGH', '{"strategy":"PARAGRAPH","minTokens":500,"maxTokens":900,"rule":"paragraph-respecting with larger context; the ruling reference is kept intact","source":"docs/04 §15"}', 'Sharia notes and committee opinions — no document in the current manifest; seeded so ingestion cannot fail on a missing collection. Defaults derived from specs/eval/kb-manifest.jsonl.', 'Notes et avis du Comité — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'Sharia notes and committee opinions — defaults derived from specs/eval/kb-manifest.jsonl.', true),
  ('82131be2-7d7e-55db-a4ec-9695fb903ad2', 'FAQ', 'Questions fréquentes', 'الأسئلة الشائعة', 'FAQ', 'PUBLIC', 'PUBLIC', 'T1_LOW', '{"strategy":"QA_PAIR","minTokens":100,"maxTokens":300,"rule":"question + answer = one chunk; the question is embedded too, which is a large recall win","source":"docs/04 §15"}', 'FAQ — no document in the current manifest; seeded so ingestion cannot fail on a missing collection. Defaults derived from specs/eval/kb-manifest.jsonl.', 'Questions fréquentes — valeurs par défaut dérivées de specs/eval/kb-manifest.jsonl.', 'FAQ — defaults derived from specs/eval/kb-manifest.jsonl.', true);
